insert into degrees (id, university, university_short, faculty, degree_name, duration_years, industry, description, atar_requirement, career_outcomes, url) values
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Accounting', 3, 'Finance', 'The Bachelor of Accounting is designed to develop your knowledge and skills in reporting, analysing and managing financial resources in business and government entities. In addition to meeting the education requirements for membership of the Australian accounting professional bodies, the degree offers flexibility for you to study in related disciplines of your interest, including finance, business information systems, management, marketing, international business and corporate sustainability.', 80, ARRAY['Accountant', 'Auditor', 'Financial Analyst', 'Tax Consultant'], 'https://programsandcourses.anu.edu.au/2026/program/BACCT'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Accounting (Honours)', 1, 'Finance', 'Students who achieve excellent academic performance in their accounting studies will be eligible to apply for the Honours year.', NULL, ARRAY['Accountant', 'Auditor', 'Financial Analyst', 'Tax Consultant'], 'https://programsandcourses.anu.edu.au/2026/program/HACCT'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Actuarial Studies', 3, 'Finance', 'Are you a maths whiz who wants stimulating work, limitless potential and an ever growing salary? This is the esteemed degree that will make you a thought leader in a wide variety of areas. With an ANU Bachelor of Actuarial Studies, you can excel in your career literally anywhere in the world. Risk is all around us - in investment markets, on the roads, from our health and the climate. This degree will teach you how to apply your mathematical talent in understanding, measuring and managing these risks. Graduates will apply mathematical, statistical, financial, economic and other skills to untangle the most complex and difficult problems facing the commercial world.', 92, ARRAY['Actuary', 'Risk Analyst', 'Insurance Analyst', 'Quantitative Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/BACTS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Actuarial Studies (Honours)', 1, 'Finance', 'Honours in Actuarial Studies is a program offered within the Research School of Finance, Actuarial Studies and Applied Statistics that offers students who have excelled in their undergraduate actuarial degree a challenging but rewarding year of study. We seek outstanding students who are keen to undertake independent research with the guidance from academic staff. Sufficiently high grades in the coursework component of the honours year will enable students to receive exemptions from some of the Associateship and Fellowship requirements of the Actuaries Institute.', NULL, ARRAY['Actuary', 'Risk Analyst', 'Insurance Analyst', 'Quantitative Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/HACTS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Advanced Computing (Honours)', 4, 'Technology', 'This is a unique, interdisciplinary program that will prepare you to be a future leader in the information and communications technology revolution. During your final year you will be able to bring together your skills and knowledge to complete an Internship, Group project for a client on a real-world problem or a Research Project.', 85, ARRAY['Software Engineer', 'Data Engineer', 'Systems Analyst', 'Cybersecurity Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/AACOM'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Advanced Computing (Research and Development) (Honours)', 4, 'Technology', 'Join us on an exciting journey tailored for students who are passionate about pushing the boundaries of computing technology. The Bachelor of Advanced Computing (Research and Development) (Honours) program is designed to immerse you in a dynamic learning environment where you''ll not only master advanced computing concepts but also engage deeply in hands-on research and development projects. From day one, you''ll dive into a blend of challenging advanced coursework that covers everything from foundational principles to cutting-edge algorithms and software engineering techniques. Classes are interactive and designed to cultivate your critical thinking and problem-solving abilities, essential skills for tackling complex real-world challenges.', 98, ARRAY['Software Engineer', 'Data Engineer', 'Systems Analyst', 'Cybersecurity Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/AACRD'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Applied Data Analytics', 3, 'Technology', 'The Bachelor of Applied Data Analytics is a three year full-time (or equivalent part-time) inter-disciplinary degree that is designed to address a global shortage of graduates with skills in data analytics as applied to high-quality, data-informed decision-making. It is designed to develop inter-disciplinary knowledge across the three base disciplines of computing, statistics and social science. You will receive exposure to best practice in data analytics as well as an opportunity to acquire knowledge in a discipline that relies on data analytics, or deepen knowledge in one of computation, statistics, or social science.', 90, ARRAY['Data Analyst', 'Business Intelligence Analyst', 'Analytics Consultant', 'Product Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/BADAN'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Applied Data Analytics (Honours)', 1, 'Technology', 'The Bachelor of Applied Data Analytics (Honours) is a one year full-time (or equivalent part-time) degree available in one of Computing, Statistics, or Social Sciences that exemplifies the ANU commitment to research-led education. Building upon the Bachelor of Applied Data Analytics, the degree will provide you with high level preparation for life as a practitioner or for undertaking a higher degree by research. You will be provided with research methods and principles training, undertake some advanced coursework, and complete a major research project.', NULL, ARRAY['Data Analyst', 'Business Intelligence Analyst', 'Analytics Consultant', 'Product Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/HADAN'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Archaeological Practice (Honours)', 1, 'Arts', 'The Bachelor of Archaeological Practice (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of Archaeological Practice, it gives you high-level preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of archaeological practice, and through the design and implementation of a research project, typically a 20,000 word thesis, that leads to the development of new understandings or that provides solutions to complex problems.', NULL, ARRAY['Archaeologist', 'Heritage Consultant', 'Collections Officer', 'Museum Project Officer'], 'https://programsandcourses.anu.edu.au/2026/program/HAPRC'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Art History and Curatorship (Honours)', 1, 'Arts', 'The Bachelor of Art History and Curatorship (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of Bachelor of Art History and Curatorship, it gives you high-level preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of art history and curatorship, and through the design and implementation of a research project, typically a 20,000 word thesis, that leads to the development of new understandings or that provides solutions to complex problems.', NULL, ARRAY['Curator', 'Gallery Coordinator', 'Collections Assistant', 'Arts Program Officer'], 'https://programsandcourses.anu.edu.au/2026/program/HAHCR'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Arts', 3, 'Arts', 'Select from a diverse range of majors across the creative arts, humanities, and social sciences, taught by world-class scholars, to create a degree that is expressly yours with the ANU Bachelor of Arts.', 80, ARRAY['Policy Officer', 'Communications Advisor', 'Research Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/BARTS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Arts (Honours)', 1, 'Arts', 'The Bachelor of Arts (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of Arts, which is the most diverse, most flexible, and most popular degree at the Australian National University, Arts Honours provides you with the exciting opportunity to design and acquit your own sophisticated, independent, large-scale research project. Working under the mentorship of the University''s internationally renowned research academics, Arts Honours allows you to develop the advanced skills and knowledge that are ideally suited to modern professional life or a higher degree by research.', NULL, ARRAY['Policy Officer', 'Communications Advisor', 'Research Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/HARTS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Arts (Honours)', 1, 'Arts', 'The Bachelor of Arts (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of Arts, which is the most diverse, most flexible, and most popular degree at the Australian National University, Arts Honours provides you with the exciting opportunity to design and acquit your own sophisticated, independent, large-scale research project. Working under the mentorship of the University''s internationally renowned research academics, Arts Honours allows you to develop the advanced skills and knowledge that are ideally suited to modern professional life or a higher degree by research.', NULL, ARRAY['Policy Officer', 'Communications Advisor', 'Research Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/HART2'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences & ANU College of Asia & the Pacific', 'Bachelor of Arts (with Year in Asia)', 4, 'Arts', 'The Bachelor of Arts is the most diverse, most flexible, and most popular degree at The Australian National University. Each of its some fifty majors, in fields throughout the arts, humanities and social sciences, is taught by truly outstanding scholars to ensure that each student receives the very best education, is engaged with cutting-edge research, and learns to think like a researcher. These majors can be coupled with more than seventy minors and specialisations to broaden or deepen your study. Regardless of your choices, your Arts degree will provide you with core skills in critical analysis and in written and oral communication, while developing your adaptability and ability to help shape change and prepare you for a multifaceted career or further study.', NULL, ARRAY['Policy Officer', 'Communications Advisor', 'Research Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/BARTY'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Asia & the Pacific', 'Bachelor of Asia-Pacific Affairs', 4, 'Government', 'The Bachelor of Asia-Pacific Affairs provides students with an in-depth exploration of Asia-Pacific regional affairs drawing on the strength of ANU in four different subject and disciplinary areas including politics and government; international relations and security; conflict and peacebuilding; history and cultural identity. This innovative program provides students an unique opportunity to understand the transnational forces and contemporary challenges facing the Asia-Pacific region, and to deepen their understanding and appreciation of different Asia-Pacific cultures.', 82, ARRAY['Policy Officer', 'International Affairs Analyst', 'Diplomatic Support Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/BAPAF'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Asia & the Pacific', 'Bachelor of Asia-Pacific Affairs (Ritsumeikan)', 4, 'Government', 'The Bachelor of Asia-Pacific Affairs provides students with an in-depth exploration of Asia-Pacific regional affairs drawing on the strength of ANU in four different subject and disciplinary areas including politics and government; international relations and security; conflict and peacebuilding; history and cultural identity. This innovative program will give students a unique opportunity to understand the transnational forces and contemporary challenges facing the Asia-Pacific region, and to deepen their understanding and appreciation of different Asia-Pacific cultures.', 82, ARRAY['Policy Officer', 'International Affairs Analyst', 'Diplomatic Support Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/BAPAR'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Asia & the Pacific', 'Bachelor of Asian Studies', 3, 'Arts', 'Engaging with Asia as a part of Asia is a strategic imperative for Australia. The Bachelor of Asian Studies provides a pathway for ambitious and adventurous people in all fields of study to gain the language skills and cultural-historical expertise critical to leading that engagement. Graduates emerge with a nuanced understanding of the Asian region and its complex national and subnational parts.', 80, ARRAY['Policy Officer', 'International Affairs Analyst', 'Diplomatic Support Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/BASIA'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Asia & the Pacific', 'Bachelor of Asian Studies (Honours)', 1, 'Arts', 'The Bachelor of Asian Studies Honours year is an opportunity for those who have completed a good pass degree to do independent research relating to Asia or the Pacific in one of the world''s leading universities. As an Honours student you will have access to the wealth of Asian-Pacific expertise across the ANU and to the great holdings of the University and the National libraries. You will have expert supervisory guidance and research training in the College of Asia and the Pacific. With a Bachelor of Asian Studies (Honours) degree, you will acquire in-depth contextual knowledge and develop the research skills you need to move on to a higher research degree and/or professional employment.', NULL, ARRAY['Policy Officer', 'International Affairs Analyst', 'Diplomatic Support Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/HASIA'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Asia & the Pacific', 'Bachelor of Asian Studies (with Year in Asia)', 4, 'Arts', 'Australia is increasingly looking to Asia - strategically, economically, politically, and culturally - and all eyes are on the graduates of tomorrow to take us there.', NULL, ARRAY['Policy Officer', 'International Affairs Analyst', 'Diplomatic Support Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/BASY'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Biotechnology', 3, 'Science', 'Place yourself at the forefront of innovation with the ANU Bachelor of Biotechnology.', 80, ARRAY['Research Assistant', 'Laboratory Analyst', 'Data Analyst', 'Science Communicator'], 'https://programsandcourses.anu.edu.au/2026/program/BBIOT'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Biotechnology (Honours)', 1, 'Science', 'The Bachelor of Biotechnology (Honours) degree exemplifies a commitment to research-led education. Biotechnology is a fast moving field where scientists use living organisms and their products, to solve real world problems facing modern society. This exciting field has broad applications in medicine, biology, agriculture, manufacturing, renewable energy and engineering. Honours allows the exploration of research possibilities in this field; it gives you preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of your discipline, and through the design and implementation of a research project, that develops new understandings or provides solutions to complex problems. Honours Specialisations are available that mirror the teaching and research strengths at the ANU in biotechnology.', NULL, ARRAY['Research Assistant', 'Laboratory Analyst', 'Data Analyst', 'Science Communicator'], 'https://programsandcourses.anu.edu.au/2026/program/HBIOT'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Business Administration', 3, 'Business', 'What does it take to start a successful new business, to lead an organisation, to plan and manage a complex project? How do leaders negotiate, resolve conflict, and manage across cultures in the global workplace?', 80, ARRAY['Business Analyst', 'Operations Manager', 'Management Consultant', 'Project Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/BBUSA'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Business Administration (Honours)', 1, 'Business', 'The Bachelor of Business Administration (Honours) builds on undergraduate studies in management and leadership. It comprises three compulsory research methodology courses, one supervised applied topic course, and the completion of a research thesis.', NULL, ARRAY['Business Analyst', 'Operations Manager', 'Management Consultant', 'Project Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/HBUSA'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Classical Studies (Honours)', 1, 'Arts', 'The Bachelor of Classical Studies (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of Classical Studies, it gives you high-level preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of classical studies (Ancient History, Ancient Greek, or Latin), and through the design and implementation of a research project, typically a 20,000 word thesis, that leads to the development of new understandings or that provides solutions to complex problems.', NULL, ARRAY['Communications Advisor', 'Program Coordinator', 'Research Officer', 'Research Assistant'], 'https://programsandcourses.anu.edu.au/2026/program/HCLAS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Commerce', 3, 'Business', 'The Bachelor of Commerce offers significant flexibility and diversity for students. The degree allows you to study one or more business areas of your interests, including Accounting, Business Analytics, Business Information Systems, Corporate Sustainability, Economic Studies, Finance, International Business, Management or Marketing.', 80, ARRAY['Management Consultant', 'Business Analyst', 'Financial Analyst', 'Operations Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/BCOMM'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Commerce (Honours)', 1, 'Business', 'Honours in Commerce is a program offered within the College of Business and Economics that offers students who have excelled in their undergraduate studies a challenging but rewarding year of study in various disciplines.', NULL, ARRAY['Management Consultant', 'Business Analyst', 'Financial Analyst', 'Operations Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/HCOMM'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Computing', 3, 'Technology', 'The Bachelor of Computing program allows students to approach computer science from either a technical, constructive angle, starting with courses in programming, or from a conceptual, critical or information and organisational management angle. It widens the approach to computing to include the creative and conceptual touch, starting by applying scripting to the application area of new media (video and audio), rather than from learning traditional general-purpose programming languages applied to algorithms. The technically oriented student can major in Software Development; whereas the more conceptually oriented student can major in Information Systems.', 80, ARRAY['Software Engineer', 'Data Engineer', 'Systems Analyst', 'Cybersecurity Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/BCOMP'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Computing (Honours)', 1, 'Technology', 'Honours in Computing is a program offered within the School of Computing that offers students who have excelled in their undergraduate studies a challenging but rewarding year of study in computer science. We seek outstanding students who are keen to undertake independent research with the guidance from academic staff, and who wish to be prepared for exciting careers as computing professionals or who wish to pursue further study.', NULL, ARRAY['Software Engineer', 'Data Engineer', 'Systems Analyst', 'Cybersecurity Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/HCOMP'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Criminology', 3, 'Law', 'Do you want to delve into an enthralling field that deals with the complexities of crime and responses to crime? Look no further.', 80, ARRAY['Policy Analyst', 'Intelligence Analyst', 'Compliance Officer', 'Justice Program Officer'], 'https://programsandcourses.anu.edu.au/2026/program/BCRIM'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Criminology (Honours)', 1, 'Law', 'The Bachelor of Criminology (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of Criminology, it gives you high-level preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of criminology, and through the design and implementation of a research project, typically a 20,000 word thesis, that leads to the development of new understandings or that provides solutions to complex problems.', NULL, ARRAY['Policy Analyst', 'Intelligence Analyst', 'Compliance Officer', 'Justice Program Officer'], 'https://programsandcourses.anu.edu.au/2026/program/HCRIM'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Design', 3, 'Design', 'The Bachelor of Design critically engages with a diverse set of concepts and practices that give students creative agency to respond to our world’s wicked problems. Courses offered in the program encourage research-driven approaches and partnerships with industry to prepare students with transferable knowledge and skills required to engage sustainably and ethically in a rapidly changing world.', NULL, ARRAY['UX Designer', 'Service Designer', 'Brand Designer', 'Creative Strategist'], 'https://programsandcourses.anu.edu.au/2026/program/BDESN'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Design (Honours)', 1, 'Design', 'The Bachelor of Design (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of Design, it gives you high-level preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of design, and through the creation and implementation of a research project, typically the formation and installation/exhibition of a coherent, imaginative, focused and speculative design project by integrating studio and contextual investigation/research, that leads to the development of new understandings or that provides solutions to complex problems.', NULL, ARRAY['UX Designer', 'Service Designer', 'Brand Designer', 'Creative Strategist'], 'https://programsandcourses.anu.edu.au/2026/program/HDESN'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Development Studies (Honours)', 1, 'Arts', 'The Bachelor of Development Studies (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of Development Studies, it gives high-level preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of development studies, and through the design and implementation of a research project, typically a 20,000 word thesis, that leads to the development of new understandings or that provides solutions to complex problems.', NULL, ARRAY['Development Program Officer', 'Policy Analyst', 'Research Officer', 'NGO Project Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/HDEVS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences & ANU College of Asia & the Pacific', 'Bachelor of Development Studies (with Year in Asia)', 4, 'Arts', 'This program is only open to students already enrolled in the BDEVS - Bachelor of Development Studies.', NULL, ARRAY['Development Program Officer', 'Policy Analyst', 'Research Officer', 'NGO Project Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/BDEVY'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Economics', 3, 'Finance', 'Why is something as superfluous as diamonds so costly, but something as essential as water so cheap? How can the cost of the coffee beans make up only a few cents of the price of a cup of coffee? With the world’s highest minimum wage rate, can Australia ever compete with low wage countries?', 80, ARRAY['Economist', 'Policy Analyst', 'Economic Consultant', 'Market Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/BECON'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Economics (Honours)', 1, 'Finance', 'Honours in Economics is a program offered within the Research School of Economics that offers students who have excelled in their undergraduate studies a challenging but rewarding year of study in economics. We seek outstanding students who are keen to undertake independent economics research with the guidance from academic staff. Past students graduating from the Honours in Economics program have been highly successful with careers in government, Industry and academia in leading institutions and organisations around the world.', NULL, ARRAY['Economist', 'Policy Analyst', 'Economic Consultant', 'Market Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/HECON'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Engineering (Honours)', 4, 'Engineering', 'Do you want to make solar energy more efficient and live in a sustainable city, or create new technologies in robotics, uncrewed aircraft and wireless internet of things? This is the degree for you!', 85, ARRAY['Engineer', 'Systems Engineer', 'Project Engineer', 'Engineering Consultant'], 'https://programsandcourses.anu.edu.au/2026/program/AENGI'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Engineering (Honours) in Software Engineering', 4, 'Engineering', 'Software Engineering is about building effective software systems that address complex problems in a broad range of domains including transport, communications, finance, medicine, science, entertainment and the arts.', 85, ARRAY['Software Engineer', 'Platform Engineer', 'DevOps Engineer', 'Technical Product Manager'], 'https://programsandcourses.anu.edu.au/2026/program/AENSE'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Engineering (Research and Development) (Honours)', 4, 'Engineering', 'Do you want to make solar energy more efficient and live in a sustainable city, or create new technologies in robotics, un-crewed aircraft and wireless internet of things?', 98, ARRAY['Engineer', 'Systems Engineer', 'Project Engineer', 'Engineering Consultant'], 'https://programsandcourses.anu.edu.au/2026/program/AENRD'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Environment and Sustainability', 3, 'Science', 'Maintaining the balance between our environment and human development is challenging. The future needs you to work on sustainable solutions to issues including increasing biodiversity loss, urbanisation and climate change.', 80, ARRAY['Sustainability Analyst', 'Environmental Consultant', 'Climate Policy Officer', 'ESG Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/BENSU'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Environment and Sustainability (Honours)', 1, 'Science', 'The Bachelor of Environment and Sustainability (Honours) degree builds on the Bachelor of Environment and Sustainability with the Environment Honours specialisation, reflecting ANU national and international leadership in research in this field. You will design and implement a unique research project on a topic relevant to environment and sustainability, preparing you for professional life or for a higher degree by research through the development of advanced knowledge of the research principles and methods and theoretical concepts of your discipline. Your research will provide new understandings of or solutions to complex problems; and you will develop skills valued by employers, including holistic thinking and evidence-based decision making.', NULL, ARRAY['Sustainability Analyst', 'Environmental Consultant', 'Climate Policy Officer', 'ESG Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/HENSU'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Finance', 3, 'Finance', 'Do you dream of living and thriving in the leading financial cities of the world - New York, London, Shanghai, Sydney or Hong Kong? Stop dreaming and get going. An ANU Bachelor of Finance will equip you to excel in the global financial marketplace.', 80, ARRAY['Financial Analyst', 'Investment Analyst', 'Risk Analyst', 'Corporate Finance Associate'], 'https://programsandcourses.anu.edu.au/2026/program/BFINN'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Finance (Honours)', 1, 'Finance', 'Honours in Finance is a program offered within the Research School of Finance, Actuarial Studies and Applied Statistics that offers students who have excelled in their undergraduate studies a challenging but rewarding year of study in finance. We seek outstanding students who are keen to undertake independent finance research with the guidance from academic staff. Past students graduating from the Honours in Finance program have been highly successful in professional practice with jobs in the leading investment banks around the world.', NULL, ARRAY['Financial Analyst', 'Investment Analyst', 'Risk Analyst', 'Corporate Finance Associate'], 'https://programsandcourses.anu.edu.au/2026/program/HFINN'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Finance, Economics and Statistics (Honours)', 4, 'Finance', 'The Bachelor of Finance, Economics and Statistics (Honours) is an elite four year honours degree. The degree is targeted at excellent undergraduate students seeking a quantitative degree program that will equip them for graduate studies in Finance, Economics or Statistics and/or that will make them desirable to prestigious Government or Industry employers. The degree will fill a gap at the ANU by providing an attractive option for outstanding undergraduates who are seeking a quantitative degree program that has applications in a wide range of business areas. The degree will comprise courses from Finance, Economics and Statistics and also relevant courses from Mathematics.', 98, ARRAY['Economist', 'Policy Analyst', 'Economic Consultant', 'Market Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/AFEST'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Genetics', 3, 'Science', 'Explore the complex and fascinating world of genetics and unravel the mysteries of DNA with the ANU Bachelor of Genetics.', 85, ARRAY['Genetics Research Assistant', 'Laboratory Scientist', 'Biotech Analyst', 'Clinical Research Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/BGENE'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Genetics (Honours)', 1, 'Science', 'The Bachelor of Genetics (Honours) degree exemplifies a commitment to research-led education. Genetics is a multidisciplinary science, which has progressed rapidly over the last fifty years, becoming increasingly important in modern society. Honours allows the exploration of research possibilities in this field from classical genetics, molecular genetics, population genetics to bioinformatics. It gives you preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of your discipline, and through the design and implementation of a research project, which develops new understandings or provides solutions to complex problems. Honours Specialisations are available that mirror the teaching and research strengths at the ANU in genetics.', NULL, ARRAY['Genetics Research Assistant', 'Laboratory Scientist', 'Biotech Analyst', 'Clinical Research Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/HGENE'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Health Science', 3, 'Medicine', 'Tackle some of the greatest health challenges of our time with the Bachelor of Health Science. The Bachelor of Health Science draws upon the world-leading strengths of ANU in medical education, biomedical science, population health, psychology, social science and public policy to prepare you for a future in medical, allied health and health-related professions. It will equip you with a broad understanding of the disciplines and concepts explored in advanced studies of health and medicine. It offers a number of different pathways and directions you may choose to follow during the Program and beyond. It offers potential pathways to the ANU Doctor of Medicine and Surgery (MCHD), Honours and vertical double degrees in Master of Public Health, Master of Science Communications. It provides you skills and knowledge to study and work in allied health, policy, public service and other health-related fields.', 90, ARRAY['Health Policy Officer', 'Public Health Analyst', 'Clinical Research Assistant', 'Health Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/BHLTH'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Health Science (Honours)', 1, 'Medicine', 'The Bachelor of Health Science (BHLTH) provides foundation knowledge of biomedical, environmental, and social health determinants; the skills to evaluate health protection initiatives; and, introduces quantitative, qualitative and mixed-methods research approaches. In the BHLTH(Hons) you will identify a relevant research question within biomedical science, clinical science, sociology of health, health policy, health economics or population health. You will then conceive an appropriate research strategy for your question, reliably collect and analyse data, and integrate your conclusions to formulate an evidence-based argument, culminating in a written thesis. Skills gained include project management, information literacy, technical writing, and giving effective oral presentations.', NULL, ARRAY['Health Policy Officer', 'Public Health Analyst', 'Clinical Research Assistant', 'Health Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/HHLTH'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Information Technology (Honours)', 1, 'Technology', 'Honours in Information Technology is a program offered within the Research School Computer Science that offers students who have excelled in their undergraduate studies a challenging but rewarding year of study in computer science. We seek outstanding students who are keen to undertake independent research with the guidance from academic staff, and who wish to be prepared for exciting careers as computing professionals or who wish to pursue further study.', NULL, ARRAY['Software Engineer', 'Data Engineer', 'Systems Analyst', 'Cybersecurity Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/HIT'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of International Business', 3, 'Business', 'Your vision is global, not local. You have the potential to lead.', 80, ARRAY['Business Development Analyst', 'Trade Analyst', 'Market Research Analyst', 'Operations Consultant'], 'https://programsandcourses.anu.edu.au/2026/program/BINBS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of International Business (Honours)', 1, 'Business', 'The Bachelor of International Business (Honours) builds on undergraduate studies in International Business. It comprises three compulsory research methodology courses, one supervised applied topic course, and the completion of a research thesis.', NULL, ARRAY['Business Development Analyst', 'Trade Analyst', 'Market Research Analyst', 'Operations Consultant'], 'https://programsandcourses.anu.edu.au/2026/program/HINBS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of International Relations', 3, 'Government', 'Can you see yourself jet-setting the globe with a career in analytics, trade, foreign affairs, journalism, international business or research? You have found the right degree. ANU is a leader in the field of International Relations. The Bachelor of International Relations will give you world-class training in International Relations, providing the skills and background you need to understand the complex and exciting world of international affairs. Our program:', 85, ARRAY['Foreign Affairs Officer', 'Policy Analyst', 'Intelligence Analyst', 'Program Officer'], 'https://programsandcourses.anu.edu.au/2026/program/BIR'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of International Relations (Honours)', 1, 'Government', 'The Bachelor of International Relations (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of International Relations, it gives you high-level preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of international relations, and through the design and implementation of a research project, typically a 20,000 word thesis, that leads to the development of new understandings or that provides solutions to complex problems.', NULL, ARRAY['Foreign Affairs Officer', 'Policy Analyst', 'Intelligence Analyst', 'Program Officer'], 'https://programsandcourses.anu.edu.au/2026/program/HIR'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences & ANU College of Asia & the Pacific', 'Bachelor of International Relations (With Year in Asia)', 4, 'Government', 'Can you see yourself jet-setting the globe with a career in trade, foreign affairs, journalism, international business or research? You have found the right degree.', NULL, ARRAY['Foreign Affairs Officer', 'Policy Analyst', 'Intelligence Analyst', 'Program Officer'], 'https://programsandcourses.anu.edu.au/2026/program/BIRY'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Asia & the Pacific', 'Bachelor of International Security Studies', 3, 'Government', 'We live in a world of major security problems. From large-scale wars and strategic competition between the major states, to threats to the environment, and challenges at home such as terrorism, cybersecurity and the impact of new technology. The Bachelor of International Security Studies (BINSS) explores the enduring problems of security and war through a broad lens. It provides students with the empirical knowledge and analytical skills to understand the history and causes of international conflict and the implications of security issues for Australia and the Asia-Pacific region. Students will develop the experience and communication skills to assess the nature of contemporary security problems, and drawing on the latest academic scholarship, engage with policy and civil society solutions to the security problems of our time.', 85, ARRAY['Security Analyst', 'Intelligence Analyst', 'Policy Officer', 'Risk Consultant'], 'https://programsandcourses.anu.edu.au/2026/program/BINSS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Asia & the Pacific', 'Bachelor of International Security Studies (Honours)', 1, 'Government', 'The International Security Studies program provides specialist training in the international, internal, and transnational security challenges currently facing the Asia-Pacific region. As an Honours student you will have access to the wealth of expertise in international security studies across the ANU and to the great holdings of the University and the National libraries. You will have expert supervisory guidance and research training in the College of Asia and the Pacific. With a Bachelor of International Security Studies (Honours) degree, you will acquire in-depth contextual knowledge and develop the research skills you need to move on to a higher research degree and/or professional employment.', NULL, ARRAY['Security Analyst', 'Intelligence Analyst', 'Policy Officer', 'Risk Consultant'], 'https://programsandcourses.anu.edu.au/2026/program/HINSS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Asia & the Pacific', 'Bachelor of International Security Studies (with Year in Asia)', 4, 'Government', 'Do you see yourself shaping Australia''s foreign policy decisions? Or working with elite international organisations like the United Nations or our top spy agencies? The Bachelor of International Security Studies can help you make your dream career a reality.', NULL, ARRAY['Security Analyst', 'Intelligence Analyst', 'Policy Officer', 'Risk Consultant'], 'https://programsandcourses.anu.edu.au/2026/program/BINSY'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Languages', 3, 'Arts', 'ANU offers an outstanding variety of programs for Australia''s next generation of language leaders, with more languages offered than at any other university in Australia. The Bachelor of Languages is an ideal way to take advantage of this expertise, through the study of two (or more) languages, in combination with other areas of interest. Your language education experience is designed to introduce you to the structural, grammatical and idiomatic components of your chosen language or languages. This is further contextualised through a critical engagement with cultural, social and historical concepts, issues and topics. You can start at beginner level, or at higher levels if you have past experience. Exciting opportunities exist for you to immerse yourself in your chosen language and culture through study abroad, and to combine your language study with a range of other areas.', 80, ARRAY['Translator', 'International Programs Officer', 'Communications Advisor', 'Cultural Liaison Officer'], 'https://programsandcourses.anu.edu.au/2026/program/BLANG'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Languages (Honours)', 1, 'Arts', 'The Bachelor of Languages (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of Languages, this program provides students with high-level preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of language studies, and through the design and implementation of a research project, an honours thesis, that leads to the development of new understandings or that provides solutions to complex problems.', NULL, ARRAY['Translator', 'International Programs Officer', 'Communications Advisor', 'Cultural Liaison Officer'], 'https://programsandcourses.anu.edu.au/2026/program/HLANG'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences & ANU College of Asia & the Pacific', 'Bachelor of Languages (with Year in Asia)', 4, 'Arts', 'ANU offers an outstanding variety of programs for Australia''s next generation of language leaders, with more languages offered than at any other university in Australia. The ANU Bachelor of Languages is a wonderful way to take advantage of that, through the study of two (or more) languages, in combination with other areas of interest.', NULL, ARRAY['Translator', 'International Programs Officer', 'Communications Advisor', 'Cultural Liaison Officer'], 'https://programsandcourses.anu.edu.au/2026/program/BLANY'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Law, Governance & Policy', 'Bachelor of Laws (Honours)', 4, 'Law', 'A student admitted to a program for a coursework award must enrol in the courses, sequences of courses, or combinations of courses, that the University determines may be included in the program for the year in which the student is admitted to the program.', 97, ARRAY['Lawyer', 'Policy Adviser', 'Legal Analyst', 'Compliance Officer'], 'https://programsandcourses.anu.edu.au/2026/program/ALLB'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Mathematical Sciences', 3, 'Science', 'Mathematics is at the core of all technological innovations.', 95, ARRAY['Data Scientist', 'Quantitative Analyst', 'Research Analyst', 'Statistician'], 'https://programsandcourses.anu.edu.au/2026/program/BMASC'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Systems & Society', 'Bachelor of Mathematical Sciences (Honours)', 1, 'Science', 'The Honours plan that will augment our newly established Bachelor of Mathematical Sciences will be an elite, research-focused program for exceptional students who want to pursue', NULL, ARRAY['Data Scientist', 'Quantitative Analyst', 'Research Analyst', 'Statistician'], 'https://programsandcourses.anu.edu.au/2026/program/HMASC'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Medical Science', 3, 'Medicine', 'Follow in the footsteps of Nobel Prize winner Howard Florey and kick-start your career in medical research with the Bachelor of Medical Science.', 85, ARRAY['Clinical Research Assistant', 'Medical Laboratory Scientist', 'Biotech Analyst', 'Health Data Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/BMEDS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Medical Science (Honours)', 1, 'Medicine', 'The Bachelor of Medical Science (Honours) degree exemplifies a commitment to research-led education. Building on the Bachelor of Medical Science, which brings together the disciplines of genetics, immunology, nutrition, physiology, microbiology, biochemistry and anatomy. Honours allows the exploration of research possibilities related to medical science from a diverse range of complementary disciplines including biology, neuroscience, chemistry and population health (to name just a few). It gives you preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of your discipline, and through the design and implementation of a research project, which develops new understandings or provides solutions to complex problems. Honours Specialisations are available that mirror the teaching and research strengths at the ANU in science, medicine and health.', NULL, ARRAY['Clinical Research Assistant', 'Medical Laboratory Scientist', 'Biotech Analyst', 'Health Data Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/HMEDS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Music', 3, 'Arts', 'The ANU Bachelor of Music nurtures outstanding musical artistry through the intersection of performance, composition, and recording. Our program fosters artistry through offering a diversity of musical experiences in an environment that encourages excellence, passion and entrepreneurship. It provides students with a unique 21st Century musical experience which includes the opportunity to explore integrated skills in music performance, composition and recording music practice, while specialising in Music Practice or Contemporary Music Production. Students have the opportunity to experiment and explore their own musical identity and practice. Our program supports students in preparing for dynamic and multifaceted successful careers as music professionals and outstanding contributors to the local, national, and global community, as musically-informed citizens and leaders.', 80, ARRAY['Performer', 'Music Educator', 'Arts Administrator', 'Producer'], 'https://programsandcourses.anu.edu.au/2026/program/BMUSI'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Music (Honours)', 1, 'Arts', 'The Bachelor of Music Honours is characterised by the concept of musical practice as a research-led process. The core of this program is a substantial piece of original research realised through either a standalone 20,000 word written document, or a project which is presented as a combination of performance, composition, recording, or other creative output and a 10,000 word written document.', NULL, ARRAY['Performer', 'Music Educator', 'Arts Administrator', 'Producer'], 'https://programsandcourses.anu.edu.au/2026/program/HMUSI'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Asia & the Pacific', 'Bachelor of Pacific Studies', 3, 'Government', 'As Australia’s engagement with the Pacific increases, so does the need for graduates with Pacific expertise. The Bachelor of Pacific Studies offers the opportunity to develop a deep understanding of the diversity, history and contemporary issues of Oceania, preparing you to take a leading role in Pacific policy and development.', 80, ARRAY['Policy Officer', 'International Affairs Analyst', 'Diplomatic Support Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/BPAST'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Asia & the Pacific', 'Bachelor of Pacific Studies (Honours)', 1, 'Government', 'The Bachelor of Pacific Studies (Honours) program is an opportunity for students interested in and dedicated to Pacific Studies to do independent research relating to the Pacific in one of the world''s leading universities. As an Honours student you will have access to the wealth of Pacific Studies expertise across the ANU and to the great holdings of the University and the National libraries. You will have expert supervisory guidance and research training in the ANU College of Asia and the Pacific. With a Bachelor of Pacific Studies (Honours) degree, you will acquire in-depth contextual knowledge and develop the research skills you need to move on to a higher research degree and/or professional employment.', NULL, ARRAY['Policy Officer', 'International Affairs Analyst', 'Diplomatic Support Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/HPAST'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Philosophy (Honours) - Science', 4, 'Science', 'Inspire your curious mind with the Bachelor of Philosophy (Honours).', 99, ARRAY['Research Assistant', 'Policy Analyst', 'Academic Program Officer', 'Communications Advisor'], 'https://programsandcourses.anu.edu.au/2026/program/APHSC'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Asia & the Pacific', 'Bachelor of Philosophy (Honours)—Humanities and Social Sciences', 4, 'Science', 'The Bachelor of Philosophy (Honours)—Humanities and Social Sciences or PhB (HaSS) is an innovative, research-focused undergraduate degree designed for intellectually curious students who want to explore their interests beyond the classroom. It’s the only program of its kind where disciplinary knowledge is enriched by a deep regional understanding of Asia and the Pacific.', 99, ARRAY['Research Assistant', 'Policy Analyst', 'Academic Program Officer', 'Communications Advisor'], 'https://programsandcourses.anu.edu.au/2026/program/AHUSS'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences & ANU College of Science & Medicine', 'Bachelor of Philosophy, Neuroscience, and Psychology', 3, 'Science', 'Explore the complex relationship between the mind and brain.', 97, ARRAY['Behavioural Analyst', 'Research Assistant', 'Health Research Officer', 'Policy Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/BPNP'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Political Science', 3, 'Government', 'Are you interested in understanding political systems in Australia and in other parts of the world? Do you want to find out what drives citizens’ political attitudes and behaviour, and how these affect policy outcomes? The Bachelor of Political Science is the only dedicated political science degree in Australia. In it, students:', 85, ARRAY['Policy Analyst', 'Political Adviser', 'Research Officer', 'Government Relations Officer'], 'https://programsandcourses.anu.edu.au/2026/program/BPLSC'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Political Science (Honours)', 1, 'Government', 'The Bachelor of Political Science (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of Political Science, it gives you high-level preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of political science, and through the design and implementation of a research project, typically a 20,000 word thesis, that leads to the development of new understandings or that provides solutions to complex problems.', NULL, ARRAY['Policy Analyst', 'Political Adviser', 'Research Officer', 'Government Relations Officer'], 'https://programsandcourses.anu.edu.au/2026/program/HPLSC'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Politics, Philosophy and Economics', 3, 'Finance', 'Are you a leader? The Australian National University is a leader too, especially in the fields of philosophy, politics and economics. This progressive and well-regarded degree will arm you with the moral, economic and political perspectives you need to make a real impact.', 94, ARRAY['Economist', 'Policy Analyst', 'Economic Consultant', 'Market Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/BPPE'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Politics, Philosophy and Economics (Honours)', 1, 'Finance', 'The Bachelor of Politics Philosophy and Economics (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of Politics Philosophy and Economics, it gives you high-level preparation for professional life or a higher degree by research. You will develop an advanced knowledge of research principles, methods and theoretical concepts of politics, philosophy and economics, and design and implement a research project, namely a 20,000 word thesis, that leads to the development of new understandings or that provides solutions to complex problems.', NULL, ARRAY['Economist', 'Policy Analyst', 'Economic Consultant', 'Market Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/HPPE'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Public Policy', 3, 'Government', 'Are you seeking a dynamic career in politics, the public service, advocacy organisations, not-for-profit social and community services or private industry?', 85, ARRAY['Policy Officer', 'Government Adviser', 'Program Evaluator', 'Public Sector Consultant'], 'https://programsandcourses.anu.edu.au/2026/program/BPPOL'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Public Policy (Honours)', 1, 'Government', 'The Bachelor of Public Policy (Honours) degree exemplifies the ANU commitment to research-led education. Building on the Bachelor of Public Policy, it gives you high-level preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of public policy, and through the design and implementation of a research project, typically a 20,000 word thesis, that leads to the development of new understandings or that provides solutions to complex problems.', NULL, ARRAY['Policy Officer', 'Government Adviser', 'Program Evaluator', 'Public Sector Consultant'], 'https://programsandcourses.anu.edu.au/2026/program/HPPOL'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Science', 3, 'Science', 'With a myriad of disciplines offered, craft a science degree that is uniquely yours with the ANU Bachelor of Science.', 80, ARRAY['Research Scientist', 'Laboratory Analyst', 'Data Analyst', 'Science Communicator'], 'https://programsandcourses.anu.edu.au/2026/program/BSC'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Science (Advanced) (Honours)', 4, 'Science', 'If you are looking for that little bit extra in your degree, the Bachelor of Science (Advanced) (Honours) provides the same breadth of opportunities as the Bachelor of Science, with the addition of Honours Pathway Options that are designed to extend your understanding and introduce you to concepts that are more advanced than standard course activities. The fourth honours year allows exploration of research possibilities in your area of interest. It prepares you for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of your discipline, and through the design and implementation of a research project that develops new understandings or provides solutions to complex problems.', 90, ARRAY['Research Scientist', 'Laboratory Analyst', 'Data Analyst', 'Science Communicator'], 'https://programsandcourses.anu.edu.au/2026/program/ASCAD'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Science (Honours)', 1, 'Science', 'The Bachelor of Science (Honours) is a diverse and flexible science degree with an emphasis on research-led education. Explore anything from biology or climate science to psychology or astrophysics. You will learn advanced knowledge of research principles as well as the methods and theoretical concepts of your discipline. You’ll also get to design your own research project which will help you to understand and provide solutions to complex problems facing our world.', NULL, ARRAY['Research Scientist', 'Laboratory Analyst', 'Data Analyst', 'Science Communicator'], 'https://programsandcourses.anu.edu.au/2026/program/HSC'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Science (Psychology)', 3, 'Science', 'What makes the human brain tick?', 80, ARRAY['Research Assistant', 'Behavioural Analyst', 'Mental Health Support Worker', 'Human Factors Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/BSPSY'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Science & Medicine', 'Bachelor of Science (Psychology) (Honours)', 1, 'Science', 'The Bachelor of Science (Psychology) (Honours) degree exemplifies a commitment to research-led education. Honours builds on the Bachelor of Science (Psychology) which will expose you to a wide range of psychological sciences, covering topics as varied as how groups interact, vision and how it can be tricked to see what is not really there, how the brain develops as a baby and how it will change again as you get older, how impulses are carried from brain to muscle, and how things go wrong in abnormal psychology. Honours allows the exploration of research possibilities in this field, it gives you preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of your discipline, and through the design and implementation of a research project, that develops new understandings or provides solutions to complex problems.', NULL, ARRAY['Research Assistant', 'Behavioural Analyst', 'Mental Health Support Worker', 'Human Factors Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/HSPSY'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Asia & the Pacific & ANU College of Science & Medicine', 'Bachelor of Science (with Year in Asia)', 4, 'Science', 'With a myriad of majors and minors, craft a science degree that is uniquely yours with the ANU Bachelor of Science.', NULL, ARRAY['Research Scientist', 'Laboratory Analyst', 'Data Analyst', 'Science Communicator'], 'https://programsandcourses.anu.edu.au/2026/program/BSCY'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Statistics', 3, 'Science', 'Statistics opens the door to understanding our world by exploring data and modelling uncertainty. As our capacity to collect data accelerates, the need for statistical expertise has never been greater. Every day, over 328.77 million terabytes of data are generated globally, and the total volume of data worldwide is expected to reach 181 zettabytes by 2026, more than doubling from 2022 levels. This explosion of information outpaces our ability to interpret it meaningfully without advanced quantitative tools.', 80, ARRAY['Statistician', 'Data Analyst', 'Quantitative Researcher', 'Risk Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/BSTAT'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Business & Economics', 'Bachelor of Statistics (Honours)', 1, 'Science', 'Honours in Statistics is a program offered within the Research School of Finance, Actuarial Studies and Applied Statistics that offers students who have excelled in their undergraduate studies a challenging but rewarding year of study in statistics. We seek outstanding students who are keen to undertake independent statistical research with the guidance from academic staff. Past students graduating from the Honours in Statistics program have been highly successful in professional practice and a number have progressed to PhD studies.', NULL, ARRAY['Statistician', 'Data Analyst', 'Quantitative Researcher', 'Risk Analyst'], 'https://programsandcourses.anu.edu.au/2026/program/HSTAT'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Visual Arts', 3, 'Arts', 'When undertaking the Bachelor of Visual Arts at the ANU, you will be immersed in a program of rigorous scholarship and intensive studio practice, tailored to your aspirations and informed by internationally renowned art practitioners within Australia’s top-ranking university. You will graduate with the essential creative skills and critical knowledge to address the grand challenges of a rapidly changing world.', NULL, ARRAY['Policy Officer', 'Communications Advisor', 'Research Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/BVART'),
(gen_random_uuid(), 'Australian National University', 'ANU', 'College of Arts & Social Sciences', 'Bachelor of Visual Arts (Honours)', 1, 'Arts', 'The Bachelor of Visual Arts (Honours) degree exemplifies ANU’s commitment to research-led education. Building on the Bachelor of Visual Arts, it gives you high-level preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of visual arts, and through the design and implementation of a research project, typically the creation and installation/exhibition of a coherent, imaginative, focused and speculative body of artworks by integrating studio and contextual investigation/research, that leads to the development of new understandings or that provides solutions to complex problems.', NULL, ARRAY['Policy Officer', 'Communications Advisor', 'Research Officer', 'Program Coordinator'], 'https://programsandcourses.anu.edu.au/2026/program/HVART');
